1	#!/usr/bin/env node
2	/*
3	 * bench/trail.mjs — the human-bar's criterion 4, as an instrument: "does this bot leave a
4	 * human-looking trail, or scars?" (GOAL.md: "no half-felled trees, no stranded drops, no
5	 * naked scars"). Until now this was a manual walk to the bot's work sites; this automates it.
6	 *
7	 * Two data sources, deliberately not conflated:
8	 *  1. The LEDGER (telemetry.js's existing JSONL) — finds WHERE the bot worked and pulls
9	 *     whatever the engine already self-reports there (chopTrees' own `result.stranded`,
10	 *     torch counts). Cheap, exact, but self-reported — the engine grading its own homework.
11	 *  2. The WORLD, read live through an already-running, already-connected inspector bot —
12	 *     confirms a bounded sample of ledger-flagged sites (and a spread of unflagged ones)
13	 *     by actually looking: floating logs, item entities on the ground, open shafts. This is
14	 *     the "verify, don't just trust the self-report" step (this project's own standing
15	 *     doctrine — see FEEDBACK.md's "unverified deferral" class of finding).
16	 *
17	 * Usage:
18	 *   node bench/trail.mjs --bot <name> --since <ISO> [--until <ISO>] --inspector-port <port>
19	 *   node bench/trail.mjs --bot <name> --since 1h --inspector-port 3160 --max-sites 15 --json
20	 *
21	 * --inspector-port must point at an ALREADY CONNECTED, DECIDER_EXCLUDE'd, --agenda-less bot
22	 * on the SAME server the ledger bot worked on (spawn.sh, no --agenda; this script disarms its
23	 * survival.js reflex itself, see stopSurvival() below — same doctrine as bench/lib/common.sh's
24	 * stop_idleguard(), extended after #106's fixture found a bare QA bot can die/respawn mid-
25	 * inspection otherwise). This script TELEPORTS that bot via RCON to each site in turn — it
26	 * does not walk there, and it never digs, places, or otherwise touches the world; read-only
27	 * by construction (no bot.dig/bot.placeBlock call anywhere below).
28	 *
29	 * Thresholds (argued in FEEDBACK.md, 2026-09-03, "criterion-4 trail inspector" — not
30	 * hard-coded folklore): see VERDICT below. Writes bench/gates/trail-<label>.json, same
31	 * convention as every other soak gate file in this tree.
32	 */
33	import fs from 'fs';
34	import path from 'path';
35	import { execFileSync } from 'child_process';
36	import { fileURLToPath } from 'url';
37	
38	const DIR = path.dirname(fileURLToPath(import.meta.url));
39	const ROOT = path.join(DIR, '..');
40	const LOGS = path.join(ROOT, 'logs');
41	
42	const argv = process.argv.slice(2);
43	const flag = (n, d = null) => { const i = argv.indexOf('--' + n); return i >= 0 ? (argv[i + 1] && !argv[i + 1].startsWith('--') ? argv[i + 1] : true) : d; };
44	const has = (n) => argv.includes('--' + n);
45	
46	const BOT = flag('bot');
47	const INSPECTOR_PORT = flag('inspector-port');
48	const LABEL = flag('label', BOT || 'trail');
49	const MAX_SITES = parseInt(flag('max-sites', '15'), 10);
50	const RCON_HOST = flag('rcon-host', '127.0.0.1');
51	const RCON_PORT = flag('rcon-port', '25598');
52	const RCON_PASS = flag('rcon-pass', 'fellocal123');
53	if (!BOT || !INSPECTOR_PORT) {
54	  console.error('usage: node bench/trail.mjs --bot <name> --since <ISO> [--until <ISO>] --inspector-port <port> [--max-sites N] [--exclude-zones "x,z,r;x,z,r"] [--json]');
55	  process.exit(2);
56	}
57	
58	// --exclude-zones "x,z,r;x,z,r;..." -- for a KNOWN contamination source sharing the same
59	// server (a different bot's own dig/shelter activity near the graded bot's own work sites,
60	// which would otherwise get misattributed to the graded bot's trail). Horizontal (x,z) only,
61	// radius in blocks -- matches how the contamination itself was described (soak #4,
62	// 2026-09-03: a stray #103 test bot dying/respawning ~20 blocks from the soak bot's spawn).
63	const EXCLUDE_ZONES = (flag('exclude-zones', '') || '').split(';').filter(Boolean).map((z) => {
64	  const [x, zc, r] = z.split(',').map(Number);
65	  return { x, z: zc, r };
66	});
67	const inExcludedZone = (pos) => EXCLUDE_ZONES.some((z) => Math.hypot(pos[0] - z.x, pos[2] - z.z) <= z.r);
68	
69	// same relative/absolute window parsing convention as playcheck.mjs
70	function parseSince(s) {
71	  if (!s) return Date.now() - 3600e3;
72	  const m = /^(\d+)(m|h|d)$/.exec(String(s).trim());
73	  if (m) return Date.now() - Number(m[1]) * { m: 60e3, h: 3600e3, d: 86400e3 }[m[2]];
74	  const t = Date.parse(s);
75	  return Number.isFinite(t) ? t : Date.now() - 3600e3;
76	}
77	const SINCE = parseSince(flag('since'));
78	const UNTIL = flag('until') ? Date.parse(flag('until')) : Date.now();
79	
80	// ---------------- RCON + inspector-bot HTTP helpers ----------------
81	function rcon(cmd) {
82	  try {
83	    return execFileSync(process.execPath, [path.join(ROOT, 'bench', 'lib', 'rcon.mjs'), RCON_HOST, RCON_PORT, RCON_PASS, cmd],
84	      { encoding: 'utf8', timeout: 8000 }).trim();
85	  } catch (e) { return 'err:' + e.message; }
86	}
87	async function evalJs(code) {
88	  const r = await fetch(`http://127.0.0.1:${INSPECTOR_PORT}/eval`, {
89	    method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ code }),
90	  });
91	  const j = await r.json();
92	  if (!j.ok) throw new Error('eval failed: ' + (j.error || 'unknown'));
93	  return j.result;
94	}
95	// stop the inspector bot's own reflex before ever teleporting it anywhere — #106's own
96	// fixture found this the hard way (a bare QA bot died to a real mob mid-setup and silently
97	// respawned elsewhere). Re-armed on every reconnect by the auto-inject stack, so call again
98	// after any relog; this script never relogs the inspector, so once is enough here.
99	async function stopSurvival() {
100	  try { await evalJs("if (globalThis.__survival) { globalThis.__survival.enabled = false; }"); } catch (e) {}
101	}
102	async function botName() {
103	  const r = await fetch(`http://127.0.0.1:${INSPECTOR_PORT}/state`);
104	  const j = await r.json();
105	  return j.name;
106	}
107	async function tpInspector(x, y, z) {
108	  const name = await botName();
109	  rcon(`tp ${name} ${x} ${y} ${z}`);
110	  // give the chunk a moment to load client-side before reading it
111	  await new Promise((r) => setTimeout(r, 1200));
112	}
113	
114	// ---------------- 1. ledger: find work sites + self-reported signals ----------------
115	function loadLedger() {
116	  const file = path.join(LOGS, `metrics-${BOT}.jsonl`);
117	  let raw;
118	  try { raw = fs.readFileSync(file, 'utf8'); } catch { return []; }
119	  const recs = [];
120	  for (const line of raw.split('\n')) {
121	    if (!line) continue;
122	    try { const r = JSON.parse(line); if (r.t >= SINCE && r.t <= UNTIL) recs.push(r); } catch {}
123	  }
124	  return recs;
125	}
126	
127	const CHOP_SKILLS = new Set(['chopTrees']);
128	const DIG_SKILLS = new Set(['safeDescend', 'mineLane', 'produce']);
129	
130	function extractSites(recs) {
131	  const chopSites = [];   // {pos, stranded, want, got, t}
132	  const digSites = [];    // {pos, digs, t, skill}
133	  let torchSurfacePlaced = 0, surfaceTaskCount = 0;
134	  let lastTorchCount = null, lastRun = null;
135	
136	  for (const r of recs) {
137	    if (r.run !== lastRun) { lastRun = r.run; lastTorchCount = null; }
138	    if (r.ev !== 'task_end' || !Array.isArray(r.pos)) continue;
139	
140	    if (CHOP_SKILLS.has(r.skill)) {
141	      const stranded = (r.result && typeof r.result.stranded === 'number') ? r.result.stranded : 0;
142	      chopSites.push({ pos: r.pos, stranded, want: r.want, got: r.got, t: r.t });
143	    }
144	    if (DIG_SKILLS.has(r.skill) && (r.digs || 0) > 0) {
145	      digSites.push({ pos: r.pos, digs: r.digs, t: r.t, skill: r.skill });
146	    }
147	    // torch density (#106's own reuse: same run-scoped, sanity-capped delta tracking) —
148	    // scoped here to SURFACE tasks only ("sky":true at task_start is a different record;
149	    // task_end doesn't carry it, so this counts torches consumed across ANY task ending
150	    // with the bot surface-exposed per dangerscan's own field if present on the record —
151	    // most task_end records don't carry `sky` at all in this ledger schema, so this falls
152	    // back to counting every torch-consuming task_end and reports it plainly as
153	    // "torches consumed, fleet-wide window" rather than overclaiming a surface-only split
154	    // the ledger schema can't actually support without the same task_start cross-reference
155	    // #106 already used — see FEEDBACK for why that reuse doesn't fit cleanly here.
156	    const heldTorch = (r.held && r.held.name === 'torch') ? r.held.count : null;
157	    if (heldTorch != null) {
158	      if (lastTorchCount != null && heldTorch < lastTorchCount) {
159	        const used = lastTorchCount - heldTorch;
160	        if (used <= (r.digs || 0) + 8) torchSurfacePlaced += used;   // same sanity cap as #106
161	      }
162	      lastTorchCount = heldTorch;
163	    }
164	    surfaceTaskCount++;
165	  }
166	  return { chopSites, digSites, torchSurfacePlaced, surfaceTaskCount };
167	}
168	
169	// ---------------- 2. cluster sites so nearby task_ends don't get inspected twice ----------------
170	function cluster(sites, radius) {
171	  const out = [];
172	  for (const s of sites) {
173	    const near = out.find((o) => Math.abs(o.pos[0] - s.pos[0]) <= radius && Math.abs(o.pos[1] - s.pos[1]) <= radius * 2 && Math.abs(o.pos[2] - s.pos[2]) <= radius);
174	    if (near) { near.members.push(s); if ((s.stranded || 0) > (near.stranded || 0)) near.stranded = s.stranded; near.digs = (near.digs || 0) + (s.digs || 0); }
175	    else out.push({ ...s, members: [s] });
176	  }
177	  return out;
178	}
179	
180	// ---------------- 3. live inspection ----------------
181	// (a) floating logs near a chop site: a log block with air directly beneath it (and the
182	// cell below THAT also air) is disconnected from the ground -- the exact half-felled-tree
183	// signature (upper trunk/canopy left standing after the lower trunk was removed).
184	async function inspectFloatingLogs(site) {
185	  await tpInspector(site.pos[0], site.pos[1] + 1, site.pos[2]);
186	  return await evalJs(`
187	    const center = new Vec3(${site.pos[0]}, ${site.pos[1]}, ${site.pos[2]});
188	    const found = [];
189	    for (let dx = -4; dx <= 4; dx++) for (let dz = -4; dz <= 4; dz++) for (let dy = -2; dy <= 12; dy++) {
190	      const p = center.offset(dx, dy, dz);
191	      const b = bot.blockAt(p);
192	      if (!b || !/_log$/.test(b.name)) continue;
193	      const below1 = bot.blockAt(p.offset(0, -1, 0));
194	      const below2 = bot.blockAt(p.offset(0, -2, 0));
195	      const air1 = !below1 || below1.name === 'air';
196	      const air2 = !below2 || below2.name === 'air';
197	      if (air1 && air2) found.push({ pos: [p.x, p.y, p.z], name: b.name });
198	    }
199	    return found.slice(0, 20);
200	  `);
201	}
202	// (b) item entities (stranded drops) near a chop site
203	async function inspectDrops(site) {
204	  return await evalJs(`
205	    const center = new Vec3(${site.pos[0]}, ${site.pos[1]}, ${site.pos[2]});
206	    const items = Object.values(bot.entities).filter((e) => e && e.name === 'item')
207	      .filter((e) => e.position && e.position.distanceTo(center) <= 10)
208	      .map((e) => ({ pos: [Math.round(e.position.x), Math.round(e.position.y), Math.round(e.position.z)] }));
209	    return items.slice(0, 20);
210	  `);
211	}
212	// (c) naked open shaft near a dig site: walk UP from the site to find where solid ground
213	// gives way to open sky-ish air (a rough "surface" heuristic -- 4+ consecutive air cells
214	// above a solid cell), then check whether that column, read back DOWN from there, is a
215	// bare >=3-deep 1-wide hole with no ladder in it. Deliberately conservative: only flags a
216	// hole that is genuinely open at the top (a real surface scar), not an internal cave void.
217	async function inspectShaft(site) {
218	  return await evalJs(`
219	    const base = new Vec3(${site.pos[0]}, ${site.pos[1]}, ${site.pos[2]});
220	    let surfaceY = null;
221	    for (let y = base.y; y <= base.y + 60; y++) {
222	      const b = bot.blockAt(new Vec3(base.x, y, base.z));
223	      if (!b) break;
224	      if (b.name !== 'air') continue;
225	      let clearAbove = true;
226	      for (let k = 1; k <= 4; k++) { const bb = bot.blockAt(new Vec3(base.x, y + k, base.z)); if (bb && bb.name !== 'air') { clearAbove = false; break; } }
227	      if (clearAbove) { surfaceY = y; break; }
228	    }
229	    if (surfaceY == null) return { open: false, reason: 'no_surface_found' };
230	    let depth = 0, hasLadder = false;
231	    for (let y = surfaceY; y >= surfaceY - 10; y--) {
232	      const b = bot.blockAt(new Vec3(base.x, y, base.z));
233	      if (!b) break;
234	      if (b.name === 'ladder' || b.name === 'scaffolding') hasLadder = true;
235	      if (b.name === 'air' || b.name === 'cave_air') { depth++; continue; }
236	      break;
237	    }
238	    return { open: depth >= 3 && !hasLadder, depth, hasLadder, surfaceY };
239	  `);
240	}
241	
242	// ---------------- 4. run it ----------------
243	const recs = loadLedger();
244	if (!recs.length) { console.error(`trail: no ledger records for ${BOT} in this window`); process.exit(1); }
245	await stopSurvival();
246	
247	const { chopSites: allChop, digSites: allDig, torchSurfacePlaced, surfaceTaskCount } = extractSites(recs);
248	const excludedChop = allChop.filter((s) => inExcludedZone(s.pos));
249	const excludedDig = allDig.filter((s) => inExcludedZone(s.pos));
250	const rawChop = allChop.filter((s) => !inExcludedZone(s.pos));
251	const rawDig = allDig.filter((s) => !inExcludedZone(s.pos));
252	if (EXCLUDE_ZONES.length) {
253	  console.error(`trail: ${EXCLUDE_ZONES.length} exclusion zone(s) active — dropped ${excludedChop.length} chop + ${excludedDig.length} dig site(s) as contaminated (known other-bot activity), not counted toward this bot's verdict`);
254	}
255	const chopClusters = cluster(rawChop, 6).sort((a, b) => (b.stranded || 0) - (a.stranded || 0));
256	const digClusters = cluster(rawDig, 6).sort((a, b) => (b.digs || 0) - (a.digs || 0));
257	
258	// prioritize ledger-flagged sites (stranded>0) first, then a spread sample of the rest,
259	// bounded to MAX_SITES total across BOTH categories (roughly half each) -- a real-time
260	// budget, not a claim every site was checked.
261	const chopBudget = Math.ceil(MAX_SITES / 2), digBudget = MAX_SITES - chopBudget;
262	const chopToCheck = chopClusters.slice(0, chopBudget);
263	const digToCheck = digClusters.slice(0, digBudget);
264	
265	const findings = { floatingLogs: [], strandedDrops: [], nakedShafts: [], sitesChecked: 0 };
266	for (const site of chopToCheck) {
267	  try {
268	    const logs = await inspectFloatingLogs(site);
269	    const drops = await inspectDrops(site);
270	    findings.sitesChecked++;
271	    if (logs.length) findings.floatingLogs.push({ site: site.pos, ledgerStranded: site.stranded, logs });
272	    if (drops.length) findings.strandedDrops.push({ site: site.pos, ledgerStranded: site.stranded, drops });
273	  } catch (e) { console.error(`trail: chop site ${site.pos} inspection failed: ${e.message}`); }
274	}
275	for (const site of digToCheck) {
276	  try {
277	    const shaft = await inspectShaft(site);
278	    findings.sitesChecked++;
279	    if (shaft.open) findings.nakedShafts.push({ site: site.pos, ...shaft });
280	  } catch (e) { console.error(`trail: dig site ${site.pos} inspection failed: ${e.message}`); }
281	}
282	
283	// ---------------- 5. verdict ----------------
284	// Thresholds argued in FEEDBACK.md, 2026-09-03 ("criterion-4 trail inspector"): a human
285	// player leaves ZERO of these as a matter of course (nobody walks away from a half-chopped
286	// tree or an open pit on purpose), so PASS is reserved for zero found. WARN acknowledges a
287	// live-inspection sample is bounded (MAX_SITES) and a single incident could be an honest
288	// one-off; FAIL is reserved for either a genuine multi-site pattern or anything at the
289	// tightest tolerance (an open shaft — the single most visually obvious scar of the four).
290	const ledgerStrandedTotal = rawChop.reduce((n, s) => n + (s.stranded || 0), 0);
291	const torchRate = surfaceTaskCount ? torchSurfacePlaced / Math.max(1, rawDig.reduce((n, s) => n + (s.digs || 0), 0)) : null;
292	
293	const reasons = [];
294	let verdict = 'PASS';
295	const worsen = (v) => { if (v === 'FAIL' || verdict === 'FAIL') verdict = 'FAIL'; else if (v === 'WARN') verdict = 'WARN'; };
296	
297	if (findings.floatingLogs.length >= 3) { worsen('FAIL'); reasons.push(`${findings.floatingLogs.length} sites with floating (half-felled) logs`); }
298	else if (findings.floatingLogs.length >= 1) { worsen('WARN'); reasons.push(`${findings.floatingLogs.length} site(s) with a floating log — spot-checked, not exhaustive`); }
299	
300	if (ledgerStrandedTotal >= 6 || findings.strandedDrops.length >= 3) { worsen('FAIL'); reasons.push(`${ledgerStrandedTotal} stranded drops reported by the engine itself across the window (${findings.strandedDrops.length} confirmed live)`); }
301	else if (ledgerStrandedTotal >= 1) { worsen('WARN'); reasons.push(`${ledgerStrandedTotal} stranded drop(s) reported, ${findings.strandedDrops.length} confirmed live`); }
302	
303	if (findings.nakedShafts.length >= 2) { worsen('FAIL'); reasons.push(`${findings.nakedShafts.length} open, uncapped shafts found — the most visually obvious scar of the four`); }
304	else if (findings.nakedShafts.length >= 1) { worsen('WARN'); reasons.push(`1 open shaft found (tight tolerance — a single one is already a real scar, not failing outright only because a bounded sample can't claim it's a pattern)`); }
305	
306	if (torchRate != null) {
307	  if (torchRate >= 0.30) { worsen('WARN'); reasons.push(`torch rate ${torchRate.toFixed(3)}/dig vs the ~0.125 (1-per-8) design target — real over-placement (see #106)`); }
308	}
309	
310	console.log(`trail ${LABEL}: ${verdict}${reasons.length ? '\n  ' + reasons.join('\n  ') : ' (clean — no half-felled trees, stranded drops, or open shafts found in the sample)'}`);
311	console.log(`  sites checked: ${findings.sitesChecked} (chop clusters seen: ${chopClusters.length}, dig clusters seen: ${digClusters.length}, budget: ${MAX_SITES})`);
312	if (torchRate != null) console.log(`  torch rate: ${torchRate.toFixed(3)}/dig (ledger-wide, not live-confirmed)`);
313	
314	const out = {
315	  label: LABEL, bot: BOT, since: new Date(SINCE).toISOString(), until: new Date(UNTIL).toISOString(),
316	  at: new Date().toISOString(), verdict, reasons,
317	  findings, ledgerStrandedTotal, torchRate,
318	  sitesSeen: { chopClusters: chopClusters.length, digClusters: digClusters.length },
319	  excludeZones: EXCLUDE_ZONES.length ? { zones: EXCLUDE_ZONES, excludedChopSites: excludedChop.length, excludedDigSites: excludedDig.length } : null,
320	};
321	fs.mkdirSync(path.join(ROOT, 'bench', 'gates'), { recursive: true });
322	fs.writeFileSync(path.join(ROOT, 'bench', 'gates', `trail-${LABEL}.json`), JSON.stringify(out, null, 2));
323	if (has('json')) console.log(JSON.stringify(out, null, 2));
324	process.exit(verdict === 'FAIL' ? 1 : 0);
325

