687	// ---------- direction gate (IDLE_TRIGGER_SPEC phase 3 acceptance, #68) ----------
688	// Team-lead's Phase 3/4 assignment: engine-dev GRADES the soak, engine-dev-3 is graded --
689	// that separation is the whole point of a mechanical, file-frozen verdict rather than a
690	// verbal "looks fine to me". Encodes §6 Phase 3's five criteria exactly as written, against
691	// whatever window --bot/--since already scoped (so `--direction-gate soak1 --since <t0>`
692	// grades one soak run, not all of history — same self-scoping instinct as --gate above,
693	// simpler here since a soak is inherently a bounded, recent window rather than a rolling
694	// ship gate that must exclude permanent pre-fix history).
695	const dgate = flag('direction-gate');
696	if (dgate && typeof dgate === 'string') {
697	  const opens = dirRecs.filter((r) => r.op === 'open');
698	  const closes = dirRecs.filter((r) => r.op === 'close');
699	  const closedEids = new Set(closes.map((c) => c.eid));
700	  const unclosed = opens.filter((o) => !closedEids.has(o.eid));
701	  const latencies = closes.map((c) => c.latency_ms).filter(Number.isFinite).sort((a, b) => a - b);
702	  const p50 = median(latencies);
703	  const p90 = latencies.length ? latencies[Math.min(latencies.length - 1, Math.ceil(0.9 * latencies.length) - 1)] : null;
