120:  const gatePath = UNTIL ? path.join(scratchDir, 'bench', 'gates', `direction-${LABEL}.json`) : path.join(ROOT, 'bench', 'gates', `direction-${LABEL}.json`);
121:  if (!fs.existsSync(gatePath)) {
122:    console.error(`humanbar: metrics.mjs did not write a gate file at ${gatePath} — cannot grade`);
125:  gate = JSON.parse(fs.readFileSync(gatePath, 'utf8'));
127:  // for it next to every other soak's gate file.
128:  fs.mkdirSync(path.join(ROOT, 'bench', 'gates'), { recursive: true });
129:  fs.writeFileSync(path.join(ROOT, 'bench', 'gates', `direction-${LABEL}.json`), JSON.stringify(gate, null, 2));
149:  // not a fail signal on its own — direction-gate's own criteria (opened/closed counts) are
156:const humanPass = Boolean(gate.pass) && playVerdict === 'PLAYING';
157:const reasons = [...(gate.reasons || [])];
161:  label: LABEL, bot: BOT, since: SINCE, until: UNTIL || new Date(untilMs).toISOString(),
165:  direction: { pass: gate.pass, opened: gate.opened, closed: gate.closed, unclosed: gate.unclosed,
166:    latency_p50_ms: gate.latency_p50_ms, latency_p90_ms: gate.latency_p90_ms, llm_calls_per_hr: gate.llm_calls_per_hr },
