681	// openEpisode/closeEpisode: the single latch. At most one open episode per bot — a second
682	// openEpisode call while one is already open, or while its per-`why` reopen backoff hasn't
683	// expired, is a no-op (backoff instead sets state:'cooldown', VISIBLE on /state — nothing is
684	// silently suppressed; see markProductive below for how reopenCount resets).
685	let _epSeq = 0;
686	const openEpisode = (why, detail, s) => {
687	  const d = A.direction;
688	  if (d.episode) return;                                         // single-latch
689	  if ((d.reopenAt[why] || 0) > s.now) { d.state = 'cooldown'; return; }  // deferred, not suppressed
690	  const eid = 'd' + Date.now().toString(36) + (++_epSeq);
691	  d.episode = { id: eid, why, openedAt: s.now, detail };
692	  d.state = 'needs_direction';
693	  d.opened++; d.byWhy[why] = (d.byWhy[why] || 0) + 1;
694	  dirEmit('open', { eid, why, project: A.project ? A.project.skill : null, detail, rung: A.owner ? A.owner.id : null, pos: s.pos || null });
695	};
696	const closeEpisode = (closedBy, skill, s) => {
697	  const d = A.direction;
698	  const ep = d.episode;
699	  if (!ep) return;
700	  const latency_ms = s.now - ep.openedAt;
701	  d.closed++;
702	  const n = d.reopenCount[ep.why] || 0;
703	  d.reopenAt[ep.why] = s.now + DIRECTION_REOPEN_MS[Math.min(n, DIRECTION_REOPEN_MS.length - 1)];
704	  d.reopenCount[ep.why] = n + 1;
705	  dirEmit('close', { eid: ep.id, why: ep.why, closedBy, latency_ms, skill: skill || null });
706	  d.episode = null;
707	  d.state = 'ok';
708	};
709	
710	// markProductive: the churn-proof productivity clock. Stamped ONLY by verified-outcome
711	// branches (never A.ownerSince — tick's NO_PROGRESS handler nulls the owner even at the
712	// floor, so ownerSince can never accumulate a window on a wedged bot). Resets the per-why
713	// reopen backoff counters (a real recovery earns a fresh, non-escalated backoff next time)
714	// and, if an episode happens to be open, closes it — a bot that fixed itself before anything
715	// answered the episode should read as self-recovered, not left open forever.
716	const markProductive = (s, src) => {
717	  A.direction.lastProductiveAt = s.now;
718	  A.direction.reopenCount = {};
719	  if (A.direction.episode) closeEpisode('self_recovered', src, s);
720	};
721	
722	// #68 (h): the central direction-episode detector. Called once per tick, immediately after
723	// the harvest block closes and BEFORE choose(s) picks a rung — so an episode opened this tick
724	// is already visible to whichever rung consults it (today: none; ESCAPE and any future
725	// consumer read A.direction/A.project directly, same as everything else in this file).
726	// Exposed as A._directionCheck for fixtures, same discipline as A._idleWorkOutcome.
727	const directionCheck = (s) => {
728	  // #103: the respawn flag lives on `bot`, not on `A` (see its own comment at module init,
729	  // above — a double-injection race can otherwise lose it). Checked first — a bot that JUST
730	  // died is provably projectless and idle, not probably, so this doesn't wait on the
731	  // composite-level edges below to eventually infer the same thing.
732	  if (bot._respawnedNeedsDirection) {
733	    bot._respawnedNeedsDirection = false;
734	    openEpisode('respawned', {}, s);
735	  }
736	  // composite level — catches EVERY current/future mutation site of p.blocked / completedOnce
737	  // / A.blocked (including a driver's own /eval writes) without a per-site call at each one.
738	  const p = A.project;
739	  const lvl = !p ? 'none'
740	    : p.blocked ? 'blocked'
741	    : (A.blocked && A.blocked.why === 'no_tool') ? 'no_tool'   // its OWN arm: projectDone() never reads A.blocked
