const skippedCap = decisions.filter((d) => d.src === 'skipped_cap').length;
const decByHour = decisions.length ? (Math.max(...decisions.map((d) => d.t)) - Math.min(...decisions.map((d) => d.t))) / 3600000 : 0;
const llmPerHr = decByHour > 0 ? llmCalls.length / decByHour : 0;

// ---- latency breakdown (soak #4 task 2, 2026-09-03, engine-dev/QA lane) ----
// The single open->close `latency_ms` graded above is exactly why soak #4's attribution
// (driver-grace bug vs Andy slowness) had to be done by hand, reading AGENDA_EVENT lines
// against decisions.jsonl. Joins each CLOSED episode's direction open/close ledger records
// to every decisions.jsonl record sharing its eid (there can be more than one -- a same-eid
// llm-miss retry, or a skipped_frozen_repeat/skipped_cap attempt before the winning one) and
// splits the total into buckets a future soak's p50/p90 can be attributed against directly:
//   - timeToFirstAttemptMs: open -> the FIRST decisions.jsonl record for this eid, of ANY
//     src including skips. Captures driver-grace + poll-interval + per-bot-gap waits BEFORE
//     the decider ever looked at this episode -- exactly soak #4's own p50 bug's shape.
//   - deciderComputeMs: sum of every attempt's own `latency_ms` (0 for a rule hit, the real
//     Ollama call duration for an llm attempt) -- pure decision-making time, already in the
//     existing schema, no new field needed.
//   - interAttemptGapMs: wall-clock time between attempts NOT accounted for by any attempt's
//     own recorded busy time (compute + dispatch) -- the rate-gate retry wait soak #4's own
//     p90 was actually made of (`PER_BOT_MIN_GAP_MS` before 4b's fix). Computed directly from
//     consecutive attempt timestamps; no new field needed.
//   - dispatchMs / standDownCarryoverMs: FORWARD-LOOKING, not yet emitted anywhere -- see the
//     coordination message to engine-dev-3 (2026-09-03): `dispatch_ms` would need decider.js
//     to time its own dirDispatch call separately (today that duration is invisible, folded
//     into interAttemptGapMs above); `standDownCarryoverMs` would need agenda.js's
//     `open`-event dirEmit to report whether the episode's own rung inherited an active
//     standDown from a PREVIOUS project (TODO 5d / test-driver's run-#6 finding: a 128665ms
//     "latency" that was standdown carryover, not decider slowness). Both report `null` (NOT
//     0 -- a missing field is not a verified zero, this file's own doctrine) until those
//     fields exist; `unattributedMs` folds whatever isn't covered by the other buckets, so
//     the breakdown is always honest about what it can't yet explain rather than silently
//     absorbing it into one bucket that happens to still be computable.
const decisionsByEid = new Map();
for (const d of decisions) { if (!decisionsByEid.has(d.eid)) decisionsByEid.set(d.eid, []); decisionsByEid.get(d.eid).push(d); }
const perEpisodeBreakdown = closes.map((c) => {
  const open = opens.find((o) => o.eid === c.eid);
  if (!open || !Number.isFinite(c.latency_ms)) return null;
  const attempts = (decisionsByEid.get(c.eid) || []).slice().sort((a, b) => a.t - b.t);
  const first = attempts[0] || null;
  const timeToFirstAttemptMs = first ? Math.max(0, first.t - open.t) : null;
  const deciderComputeMs = attempts.length ? attempts.reduce((n, a) => n + (Number.isFinite(a.latency_ms) ? a.latency_ms : 0), 0) : null;
  const dispatchAttempts = attempts.filter((a) => Number.isFinite(a.dispatch_ms));
  const dispatchMs = dispatchAttempts.length ? dispatchAttempts.reduce((n, a) => n + a.dispatch_ms, 0) : null;
  let interAttemptGapMs = 0;
  for (let i = 1; i < attempts.length; i++) {
    const prevBusyMs = (Number.isFinite(attempts[i - 1].latency_ms) ? attempts[i - 1].latency_ms : 0)
      + (Number.isFinite(attempts[i - 1].dispatch_ms) ? attempts[i - 1].dispatch_ms : 0);
    interAttemptGapMs += Math.max(0, (attempts[i].t - attempts[i - 1].t) - prevBusyMs);
  }
  const standDownCarryoverMs = (open.standDown && Number.isFinite(open.standDown.until))
    ? Math.max(0, Math.min(open.standDown.until, c.t) - open.t) : null;
  const accountedMs = [timeToFirstAttemptMs, deciderComputeMs, dispatchMs, interAttemptGapMs, standDownCarryoverMs]
    .filter(Number.isFinite).reduce((a, b) => a + b, 0);
  return {
    eid: c.eid, why: c.why, closedBy: c.closedBy, attempts: attempts.length, totalLatencyMs: c.latency_ms,
    timeToFirstAttemptMs, deciderComputeMs, dispatchMs, interAttemptGapMs, standDownCarryoverMs,
    unattributedMs: Math.round(Math.max(0, c.latency_ms - accountedMs)),
  };
}).filter(Boolean);
const bucketStats = (key) => {
  const vals = perEpisodeBreakdown.map((e) => e[key]).filter(Number.isFinite).sort((a, b) => a - b);
  if (!vals.length) return { n: 0, p50_ms: null, p90_ms: null };
  return { n: vals.length, p50_ms: median(vals), p90_ms: vals[Math.min(vals.length - 1, Math.ceil(0.9 * vals.length) - 1)] };
};
const latencyBreakdown = {
  perEpisode: perEpisodeBreakdown,
  aggregate: {
    timeToFirstAttempt: bucketStats('timeToFirstAttemptMs'),
    deciderCompute: bucketStats('deciderComputeMs'),
    dispatch: bucketStats('dispatchMs'),
    interAttemptGap: bucketStats('interAttemptGapMs'),
    standDownCarryover: bucketStats('standDownCarryoverMs'),
    unattributed: bucketStats('unattributedMs'),
  },
  pendingFields: {
    dispatch_ms: 'decider.js does not yet time its dirDispatch call separately (proposed to engine-dev-3, 2026-09-03) -- folded into interAttemptGap until it lands',
    standDown: 'agenda.js\'s open-event dirEmit does not yet report inherited standDown state (proposed to engine-dev-3, 2026-09-03, ties to TODO 5d) -- carryover is invisible (reads as unattributed or interAttemptGap) until it lands',
  },
};

