808	  if (p90 == null || p90 >= 120000) reasons.push(`latency p90 ${p90 == null ? 'n/a' : Math.round(p90 / 1000) + 's'} -- must be <120s`);
809	  // extrapolating to a per-hour rate from a short or thin window is noise, not a measurement
810	  // (2 calls in 30s reads as "240/hr" and would fail a real, healthy soak) -- same MIN_N
811	  // instinct as rate()'s suppression elsewhere in this file, applied to a window instead of a
