1	// bench/lib/latency-breakdown.mjs — metrics.mjs --direction-gate's latency attribution (task 2,
2	// 2026-09-03, engine-dev/QA lane). The single open->close `latency_ms` metrics.mjs already
3	// grades is exactly why soak #4's own attribution (driver-grace bug vs Andy slowness) had to be
4	// done by hand, reading AGENDA_EVENT lines against decisions.jsonl. This joins each CLOSED
5	// episode's direction open/close ledger records to every decisions.jsonl record sharing its eid
6	// (there can be more than one — a same-eid llm-miss retry, or a skipped_frozen_repeat/
7	// skipped_cap attempt before the winning one) and splits the total into buckets a future soak's
8	// p50/p90 can be attributed against directly, instead of hand-reading logs:
9	//
10	//   - timeToFirstAttemptMs: open -> the FIRST decisions.jsonl record for this eid, of ANY src
11	//     including skips. Captures driver-grace + poll-interval + per-bot-gap waits BEFORE the
12	//     decider ever looked at this episode — exactly soak #4's own p50 bug's shape (re-run on
13	//     soak #4's real data: timeToFirstAttempt p50 == the graded latency_p50_ms EXACTLY, 76456ms
14	//     — the entire p50 floor was structural wait-before-first-attempt, zero decider compute).
15	//   - deciderComputeMs: sum of every attempt's own `latency_ms` (0 for a rule hit, the real
16	//     Ollama call duration for an llm attempt) — pure decision-making time, already in the
17	//     existing decisions.jsonl schema, no new field needed.
18	//   - interAttemptGapMs: wall-clock time between attempts NOT accounted for by any attempt's
19	//     own recorded busy time (compute + dispatch) — the rate-gate retry wait soak #4's own p90
20	//     was actually made of (PER_BOT_MIN_GAP_MS, before TODO 4b's fix). Computed directly from
21	//     consecutive attempt timestamps; no new field needed.
22	//   - dispatchMs / standDownCarryoverMs: FORWARD-LOOKING, not yet emitted anywhere — see the
23	//     coordination message to engine-dev-3 (2026-09-03, task 2). `dispatchMs` needs decider.js
24	//     to time its own dirDispatch call separately (today folded into interAttemptGapMs);
25	//     `standDownCarryoverMs` needs agenda.js's open-event dirEmit to report an inherited
26	//     standDown (TODO 5d / test-driver's run-#6 finding: a 128665ms "latency" that was
27	//     standdown carryover, not decider slowness). Both report `null` — not 0, a missing field
28	//     is not a verified zero, this codebase's own doctrine — until those fields exist.
29	//   - unattributedMs: whatever the other buckets don't cover, so the breakdown is always
30	//     honest about what it can't yet explain rather than silently absorbing it into a bucket
31	//     that happens to still be computable.
32	//
33	// Pure functions, no fs/network — bench/fixtures/latency-breakdown.mjs tests this hermetically
34	// with synthetic open/close/decisions records; metrics.mjs imports the same code for real runs.
35	
36	const median = (a) => { if (!a.length) return null; const s = [...a].sort((x, y) => x - y); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
37	
38	// open: {eid,t,standDown?:{rung,until}} | close: {eid,t,why,closedBy,latency_ms}
39	// attempts: decisions.jsonl records sharing this eid, ANY order (sorted internally):
40	//   {t, latency_ms?, dispatch_ms?}
41	export function computeEpisodeBreakdown(open, close, attempts) {
42	  const sorted = (attempts || []).slice().sort((a, b) => a.t - b.t);
43	  const first = sorted[0] || null;
44	  const timeToFirstAttemptMs = first ? Math.max(0, first.t - open.t) : null;
45	  const deciderComputeMs = sorted.length
46	    ? sorted.reduce((n, a) => n + (Number.isFinite(a.latency_ms) ? a.latency_ms : 0), 0) : null;
47	  const dispatchAttempts = sorted.filter((a) => Number.isFinite(a.dispatch_ms));
48	  const dispatchMs = dispatchAttempts.length ? dispatchAttempts.reduce((n, a) => n + a.dispatch_ms, 0) : null;
49	  let interAttemptGapMs = 0;
50	  for (let i = 1; i < sorted.length; i++) {
51	    const prevBusyMs = (Number.isFinite(sorted[i - 1].latency_ms) ? sorted[i - 1].latency_ms : 0)
52	      + (Number.isFinite(sorted[i - 1].dispatch_ms) ? sorted[i - 1].dispatch_ms : 0);
53	    interAttemptGapMs += Math.max(0, (sorted[i].t - sorted[i - 1].t) - prevBusyMs);
54	  }
55	  const standDownCarryoverMs = (open.standDown && Number.isFinite(open.standDown.until))
56	    ? Math.max(0, Math.min(open.standDown.until, close.t) - open.t) : null;
57	  const accountedMs = [timeToFirstAttemptMs, deciderComputeMs, dispatchMs, interAttemptGapMs, standDownCarryoverMs]
58	    .filter(Number.isFinite).reduce((a, b) => a + b, 0);
59	  return {
60	    eid: close.eid, why: close.why, closedBy: close.closedBy, attempts: sorted.length, totalLatencyMs: close.latency_ms,
61	    timeToFirstAttemptMs, deciderComputeMs, dispatchMs, interAttemptGapMs, standDownCarryoverMs,
62	    unattributedMs: Number.isFinite(close.latency_ms) ? Math.round(Math.max(0, close.latency_ms - accountedMs)) : null,
63	  };
64	}
65	
66	function bucketStats(perEpisode, key) {
67	  const vals = perEpisode.map((e) => e[key]).filter(Number.isFinite).sort((a, b) => a - b);
68	  if (!vals.length) return { n: 0, p50_ms: null, p90_ms: null };
69	  return { n: vals.length, p50_ms: median(vals), p90_ms: vals[Math.min(vals.length - 1, Math.ceil(0.9 * vals.length) - 1)] };
70	}
71	
72	// opens/closes: direction ledger records (any order — matched by eid). decisions: the
73	// full decisions.jsonl array (any bots/eids — filtered here by eid membership in closes).
74	export function aggregateLatencyBreakdown(opens, closes, decisions) {
75	  const decisionsByEid = new Map();
76	  for (const d of decisions || []) {
77	    if (!decisionsByEid.has(d.eid)) decisionsByEid.set(d.eid, []);
78	    decisionsByEid.get(d.eid).push(d);
79	  }
80	  const perEpisode = closes
81	    .map((c) => {
82	      const open = opens.find((o) => o.eid === c.eid);
83	      if (!open || !Number.isFinite(c.latency_ms)) return null;
84	      return computeEpisodeBreakdown(open, c, decisionsByEid.get(c.eid) || []);
85	    })
86	    .filter(Boolean);
87	  return {
88	    perEpisode,
89	    aggregate: {
90	      timeToFirstAttempt: bucketStats(perEpisode, 'timeToFirstAttemptMs'),
91	      deciderCompute: bucketStats(perEpisode, 'deciderComputeMs'),
92	      dispatch: bucketStats(perEpisode, 'dispatchMs'),
93	      interAttemptGap: bucketStats(perEpisode, 'interAttemptGapMs'),
94	      standDownCarryover: bucketStats(perEpisode, 'standDownCarryoverMs'),
95	      unattributed: bucketStats(perEpisode, 'unattributedMs'),
96	    },
97	    pendingFields: {
98	      dispatch_ms: 'decider.js does not yet time its dirDispatch call separately (proposed to engine-dev-3, 2026-09-03) -- folded into interAttemptGap until it lands',
99	      standDown: 'agenda.js\'s open-event dirEmit does not yet report inherited standDown state (proposed to engine-dev-3, 2026-09-03, ties to TODO 5d) -- carryover is invisible (reads as unattributed or interAttemptGap) until it lands',
100	    },
101	  };
102	}
