1	#!/usr/bin/env node
2	/*
3	 * bench/playcheck.mjs — "does this bot look like a person playing, or is it standing
4	 * around?" A node reader over telemetry.js's existing JSONL ledger. Nothing new is
5	 * instrumented; this is a summarizer, not a scorer.
6	 *
7	 *   node bench/playcheck.mjs                       # all bots, last 30 minutes
8	 *   node bench/playcheck.mjs --bot LokalLothar      # one bot
9	 *   node bench/playcheck.mjs --since 2h             # relative window ("30m", "2h", "1d")
10	 *   node bench/playcheck.mjs --since 2026-09-01     # or an absolute date (Date.parse)
11	 *   node bench/playcheck.mjs --json                 # machine-readable
12	 *   node bench/playcheck.mjs --dir ../bots/logs      # point at a different logs dir
13	 *                                                    # (e.g. running from a worktree)
14	 *   node bench/playcheck.mjs --until <ISO>           # pin the window's END for a RETROACTIVE
15	 *                                                    # grade (default: Date.now(), i.e. "live").
16	 *                                                    # Without this, stationaryPct/productive-
17	 *                                                    # ActionsPer10Min silently stretch to
18	 *                                                    # (real-now - since) even when the caller
19	 *                                                    # (e.g. humanbar.mjs) only wants a bounded
20	 *                                                    # hour graded some time after it closed.
21	 *
22	 * WHY THIS EXISTS: every metric this project has (FSR, assertTask verdicts, rung
23	 * counters) is internal — none of it says what a human WATCHING the bot would
24	 * conclude. A bot can pass every assertTask and still look dead on screen (see: the
25	 * chopTrees-kit_missing / collectDrops-picked:0 loop this file's own dry run caught
26	 * live on the first try). This reads ONLY observable behavior: things a person
27	 * standing next to the bot could see it do. Internal success/fail verdicts never
28	 * enter the verdict line below.
29	 *
30	 * DESIGN CONSTRAINT, deliberately kept: this is a reader + summarizer over the
31	 * EXISTING ledger (telemetry.js schema v2), not a new metrics pipeline. Where an
32	 * observable needs something the ledger doesn't carry, that is reported as a
33	 * GAP line, not faked with a new instrument. See the "chat" section below for the
34	 * one place this reads outside the JSONL ledger (the plain-text runner log), and
35	 * why that's a read of EXISTING data rather than new instrumentation.
36	 */
37	
38	import fs from 'fs';
39	import path from 'path';
40	import { fileURLToPath } from 'url';
41	
42	const DIR = path.dirname(fileURLToPath(import.meta.url));
43	const ROOT = path.join(DIR, '..');
44	
45	const argv = process.argv.slice(2);
46	const flag = (n, d = null) => { const i = argv.indexOf('--' + n); return i >= 0 ? (argv[i + 1] && !argv[i + 1].startsWith('--') ? argv[i + 1] : true) : d; };
47	const has = (n) => argv.includes('--' + n);
48	
49	// --dir overrides the logs directory — needed when running from a git worktree, where
50	// runtime data (logs/, untracked) doesn't exist locally; the bots write it wherever
51	// runner.js actually runs from. Defaults to <script>/../logs, same convention as metrics.mjs.
52	const LOGS = flag('dir') ? path.resolve(flag('dir')) : path.join(ROOT, 'logs');
53	
54	// ---------- window ----------
55	// "30m" / "2h" / "1d" convenience on top of metrics.mjs's existing Date.parse support —
56	// a live dry-run wants "how has it been for the last half hour", not an ISO timestamp.
57	function parseSince(s) {
58	  if (!s) return Date.now() - 30 * 60 * 1000; // default: last 30 minutes
59	  const m = /^(\d+)(m|h|d)$/.exec(String(s).trim());
60	  if (m) {
61	    const n = Number(m[1]);
62	    const mult = { m: 60e3, h: 3600e3, d: 86400e3 }[m[2]];
63	    return Date.now() - n * mult;
64	  }
65	  const t = Date.parse(s);
66	  return Number.isFinite(t) ? t : Date.now() - 30 * 60 * 1000;
67	}
68	const SINCE = parseSince(flag('since'));
69	// NOW anchors the window's END for stationaryPct/productiveActionsPer10Min's own denominator.
70	// Defaults to the real clock (live "how's it doing right now" usage); --until pins it for a
71	// retroactive grade, so a delayed run doesn't silently stretch the window past the bot's actual
72	// graded hour (see the humanbar.mjs usage note above -- this is exactly the bug it hit).
73	const untilFlag = flag('until');
74	const untilParsed = untilFlag ? Date.parse(untilFlag) : NaN;
75	const NOW = Number.isFinite(untilParsed) ? untilParsed : Date.now();
76	const WINDOW_MS = Math.max(1, NOW - SINCE);
77	
78	// ---------- load one bot's ledger, filtered to the window ----------
79	function loadBot(botName) {
80	  const file = path.join(LOGS, `metrics-${botName}.jsonl`);
81	  const recs = [];
82	  let raw;
83	  try { raw = fs.readFileSync(file, 'utf8'); } catch { return recs; }
84	  for (const line of raw.split('\n')) {
85	    if (!line.trim()) continue;
86	    let r; try { r = JSON.parse(line); } catch { continue; }
87	    if (r.t < SINCE) continue;
88	    recs.push(r);
89	  }
90	  return recs;
91	}
92	
93	function listBots() {
94	  let files = [];
95	  try { files = fs.readdirSync(LOGS).filter((f) => /^metrics-.*\.jsonl$/.test(f)); } catch { /* none yet */ }
96	  return files.map((f) => f.replace(/^metrics-|\.jsonl$/g, '')).sort();
97	}
98	
99	// ---------- chat: the ONE place this reads outside the JSONL ledger ----------
100	// telemetry.js has no chat event at all — chat only ever reaches the runner's plain-text
101	// stdout log (logs/<bot>.log). That is EXISTING data (the runner already writes it for
102	// every bot, every line, unconditionally) — reading it is not new instrumentation, it's
103	// reading a different file this project already produces. A shared Minecraft world means
104	// one bot's log also contains OTHER bots' chat (verified live this session: ShakeoutShorty's
105	// lines showed up inside ZitterZorro's own log) — filtered out below by requiring the
106	// bracketed `[botName]` prefix AND (for <chat> lines specifically) the speaker name to match,
107	// since <say> is always the bot's own narration but <chat> echoes the whole server.
108	const CHAT_LINE = /^\[(\S+)\]\s+\[(\S+)\]\s+<(say|chat)>\s*(?:<(\S+)>\s*)?(.*)$/;
109	function readChat(botName) {
110	  let raw;
111	  try { raw = fs.readFileSync(path.join(LOGS, `${botName}.log`), 'utf8'); } catch { return { lines: [], gap: true }; }
112	  const lines = [];
113	  for (const line of raw.split('\n')) {
114	    const m = CHAT_LINE.exec(line);
115	    if (!m) continue;
116	    const t = Date.parse(m[1]);
117	    if (!Number.isFinite(t) || t < SINCE) continue;
118	    const kind = m[3], speaker = m[4], text = m[5];
119	    if (kind === 'chat' && speaker && speaker !== botName) continue; // another bot's line, shared world chat
120	    lines.push({ t, text });
121	  }
122	  return { lines, gap: false };
123	}
124	
125	// ---------- per-bot aggregation ----------
126	const LOG_ITEM = /_log$/;
127	
128	function summarize(botName) {
129	  const recs = loadBot(botName);
130	  if (!recs.length) return null;
131	
132	  let blocksMined = 0;                 // dig_batch is the authoritative total: it flushes
133	                                        // every 64 digs AND at every task boundary, whether
134	                                        // or not a task was active, so it never double-counts
135	                                        // against task_end.digs (which is per-task only).
136	  let itemsGained = 0;
137	  const itemsGainedByName = {};
138	  let itemsDeposited = 0;
139	  let logsChopped = 0;
140	  let structuresPlaced = 0;
141	  let animalsKilled = 0;
142	  let distanceTraveled = 0;            // sum(task_end.moved) + sum(standalone goto.moved) —
143	                                        // NOT both for the same movement: a goto's `moved`
144	                                        // is already folded into its owning task's `moved`
145	                                        // via the same 500ms sampler (telemetry.js:188-189),
146	                                        // so only goto events with tid:null (no owning task)
147	                                        // are added here, to avoid counting the same steps twice.
148	  let deaths = 0;
149	  let panics = 0;
150	  let taskCount = 0;
151	  let noOpTasks = 0;
152	  let productiveTasks = 0;
153	  let activeMs = 0;                    // sum of task durations — the ledger's only direct
154	                                        // "something was running" signal (see GAPS below)
155	
156	  for (const r of recs) {
157	    if (r.ev === 'dig_batch') blocksMined += r.digs || 0;
158	    if (r.ev === 'death') deaths++;
159	    if (r.ev === 'panic' && r.phase === 'enter') panics++;
160	    if (r.ev === 'goto' && r.tid == null) distanceTraveled += r.moved || 0;
161	    if (r.ev === 'task_end') {
162	      taskCount++;
163	      activeMs += r.ms || 0;
164	      distanceTraveled += r.moved || 0;
165	      structuresPlaced += r.placed || 0;
166	      if (r.skill === 'huntAnimals' && r.outcome === 'ok') animalsKilled++;
167	      const collected = r.collected || {};
168	      let taskItems = 0;
169	      for (const [name, n] of Object.entries(collected)) {
170	        itemsGained += n; taskItems += n;
171	        itemsGainedByName[name] = (itemsGainedByName[name] || 0) + n;
172	        if (LOG_ITEM.test(name) && r.skill === 'chopTrees') logsChopped += n;
173	      }
174	      if (r.skill === 'depositToChest') itemsDeposited += taskItems;
175	      // Soak-#4 human-bar prep: a genuine RESTOCK depot search that comes up short
176	      // (checked several chests, none had what was needed — `outcome:'ok', result.
177	      // stocked:false`) reports `moved:0, digs:0, placed:0, collected:{}` even after
178	      // real `gotos` (short chest-to-chest hops don't register on the same distance
179	      // tracker full travel does) — measured directly against real ledgers before this
180	      // fix: EVERY stocked:false restock record checked (10/10) showed gotos:8-9,
181	      // ms~2000, and all four of the OLD observable fields at zero. A person watching
182	      // a bot walk between three chests and come away empty-handed would call that
183	      // "looking for supplies", not "standing still" — `gotos>0` is a real, visible
184	      // travel-attempt count (never fabricated for a task that never actually moved:
185	      // the genuinely-stuck #101 case — ensureTool wedged in place on a table it
186	      // can't re-place — reports gotos:0, so this does not blur the two apart).
187	      const observable = (r.digs || 0) > 0 || (r.placed || 0) > 0 || (r.moved || 0) > 1
188	        || taskItems > 0 || (r.gotos || 0) > 0;
189	      if (observable) productiveTasks++; else noOpTasks++;
190	    }
191	  }
192	
193	  const stationaryMs = Math.max(0, WINDOW_MS - activeMs);
194	  const stationaryPct = Math.round((stationaryMs / WINDOW_MS) * 1000) / 10;
195	  const per10 = productiveTasks / (WINDOW_MS / 600000);
196	
197	  const chat = readChat(botName);
198	  const chatCount = chat.lines.length;
199	
200	  return {
201	    bot: botName,
202	    windowMs: WINDOW_MS,
203	    blocksMined, logsChopped, structuresPlaced, animalsKilled,
204	    itemsGained, itemsGainedByName, itemsDeposited,
205	    distanceTraveled: Math.round(distanceTraveled * 10) / 10,
206	    deaths, panics,
207	    taskCount, productiveTasks, noOpTasks,
208	    noOpFraction: taskCount ? Math.round((noOpTasks / taskCount) * 1000) / 1000 : null,
209	    stationaryPct,
210	    productiveActionsPer10Min: Math.round(per10 * 10) / 10,
211	    chatCount,
212	    chatGap: chat.gap,
213	  };
214	}
215	
216	// ---------- verdict: a plain threshold on the one number a watcher would actually use.
217	// Deliberately not a weighted score (design constraint: reader + summarizer, not a
218	// tunable scorer). Stationary% is primary because it's the most direct answer to "is it
219	// doing anything at all"; productive actions/10min breaks the tie for a bot that moves a
220	// lot but produces nothing (a wedge-and-retry loop would score low-stationary here, so
221	// per10 catches it where stationary% alone would be fooled).
222	function verdict(s) {
223	  if (s.stationaryPct >= 70 && s.productiveActionsPer10Min < 0.5) return 'IDLE';   // also
224	                                                            // covers taskCount:0 (per10 is 0)
225	  if (s.stationaryPct >= 40 || s.productiveActionsPer10Min < 1) return 'SPARSE';
226	  return 'PLAYING';
227	}
228	
229	function oneLine(s) {
230	  const bits = [];
231	  if (s.blocksMined) bits.push(`${s.blocksMined} blocks mined`);
232	  if (s.logsChopped) bits.push(`${s.logsChopped} logs chopped`);
233	  if (s.structuresPlaced) bits.push(`${s.structuresPlaced} placed`);
234	  if (s.animalsKilled) bits.push(`${s.animalsKilled} kills`);
235	  if (s.itemsGained && !s.blocksMined && !s.logsChopped) bits.push(`${s.itemsGained} items gathered`);
236	  bits.push(`${s.distanceTraveled}m traveled`);
237	  if (s.deaths) bits.push(`${s.deaths} death${s.deaths === 1 ? '' : 's'}`);
238	  if (s.panics) bits.push(`${s.panics} panic${s.panics === 1 ? '' : 's'}`);
239	  bits.push(`${s.stationaryPct}% stationary`);
240	  const v = verdict(s);
241	  return `${s.bot}: ${bits.join(', ')} — ${v}`;
242	}
243	
244	// ---------- main ----------
245	const botArg = flag('bot');
246	const bots = botArg ? [botArg] : listBots();
247	const results = bots.map(summarize).filter(Boolean);
248	
249	if (has('json')) {
250	  console.log(JSON.stringify({ since: SINCE, now: NOW, windowMs: WINDOW_MS, bots: results }, null, 2));
251	} else {
252	  console.log(`playcheck :: window ${new Date(SINCE).toISOString()} -> ${untilFlag ? new Date(NOW).toISOString() : 'now'} (${Math.round(WINDOW_MS / 60000)}m)`);
253	  console.log('---');
254	  if (!results.length) {
255	    console.log(botArg ? `no ledger for ${botArg} in this window` : 'no bots with ledger data in this window');
256	  }
257	  for (const s of results) {
258	    console.log(oneLine(s));
259	    const detail = [];
260	    if (s.noOpFraction != null) detail.push(`no-op tasks: ${Math.round(s.noOpFraction * 100)}% (${s.noOpTasks}/${s.taskCount})`);
261	    detail.push(`productive actions/10min: ${s.productiveActionsPer10Min}`);
262	    detail.push(`chat lines: ${s.chatCount}${s.chatGap ? ' (log file missing — GAP)' : ''}`);
263	    if (s.itemsDeposited) detail.push(`deposited: ${s.itemsDeposited} items`);
264	    console.log('    ' + detail.join(' | '));
265	  }
266	  console.log('---');
267	  console.log('LEDGER GAPS (things this instrument could not read from the existing ledger):');
268	  console.log('  - no continuous position stream outside task/goto spans: "stationary" is inferred');
269	  console.log('    from task_end.ms coverage of the window, not a real position trace. A bot that');
270	  console.log('    is technically inside a task but wedged/frozen would still count as "active" time');
271	  console.log('    unless it also failed the observable-output check (see noOpFraction).');
272	  console.log('  - chest deposits: telemetry.js defines M.chest() but nothing calls it — deposit');
273	  console.log('    counts here come from depositToChest task_end.collected instead, which may not');
274	  console.log('    be populated the same way by every deposit path.');
275	  console.log('  - chat "spam" is reported as a raw line count, not classified no-op vs meaningful —');
276	  console.log('    that would need either a chat-content event in the ledger or a text-pattern guess');
277	  console.log('    this instrument deliberately avoids. noOpFraction (ledger-grounded) is the closest');
278	  console.log('    proxy: a high chat count alongside a high noOpFraction is the "spam" signature.');
279	}
