4163	// ---------- depositToChest ----------
4164	S.define('depositToChest', {
4165	  description: 'Deposit inventory into a chest/barrel (keeps tools/armor/food by default). Announces a DEPOT ledger line.',
4166	  params: { pos: 'optional {x,y,z} of the chest (else: nearest chest within 32)', keep: 'extra item names to keep', keepTools: 'bool (default true)', items: 'optional whitelist: deposit ONLY these item names' },
4167	  validate: (a) => {
4168	    if (a.pos && ![a.pos.x, a.pos.y, a.pos.z].every((n) => typeof n === 'number')) return 'pos must be {x,y,z} numbers';
4169	    return null;
4170	  },
4171	  fn: async (ctx) => {
4172	    const { bot, args } = ctx;
4173	    let chest = null;
4174	    if (args.pos) {
4175	      const want = new Vec3(args.pos.x, args.pos.y, args.pos.z);
4176	      chest = bot.blockAt(want);
4177	      if (!chest || !CONTAINERS.has(chest.name)) {
4178	        // stale coord (moved depot chest) — re-find the nearest chest near the registered
4179	        // spot before refusing, so a nudged chest doesn't loop the DEPOSIT rung. (#76)
4180	        const moved = resolveContainer(bot, want, { types: CONTAINERS, reach: true });
4181	        if (moved) { chest = bot.blockAt(moved); if (chest) ctx.log(`deposit chest re-resolved to ${moved.x},${moved.y},${moved.z}`); }
4182	      }
4183	      if (!chest || !CONTAINERS.has(chest.name)) {
4184	        throw fatal('not_found', `no chest at ${args.pos.x},${args.pos.y},${args.pos.z} (found ${chest ? chest.name : 'unloaded'})`, 'check the coordinates (DEPOT.md) and restart');
4185	      }
4186	    } else {
4187	      chest = bot.findBlock({ matching: blockIds(bot, [...CONTAINERS]), maxDistance: 32 });
4188	      if (!chest) throw fatal('not_found', 'no chest/barrel within 32 blocks', 'pass pos:{x,y,z} (see DEPOT.md) or place a chest');
4189	    }
4190	    ctx.setPhase('travelling', 'Dropping off the loot at the chest.');
4191	    // GoalNear can stall forever in partial-path recalc when the spots around a
4192	    // cluttered chest are unstandable — fall back to a look-at goal (seen live).
4193	    try { await ctx.gotoNear(chest.position, 2, 25000); }
4194	    catch (_) {
4195	      await ctx.retry('walk to chest', () => ctx.gotoSee(chest.position, 25000), 2);
4196	    }
4197	    const eyeDist = chest.position.offset(0.5, 0.5, 0.5).distanceTo(bot.entity.position.offset(0, 1.6, 0));
4198	    if (eyeDist > 4.5) throw fatal('unreachable', 'cannot get within reach of the chest', 'clear the approach or pick another chest');
4199	
4200	    const keepSet = new Set(args.keep || []);
4201	    const keepTools = args.keepTools !== false;
4202	    const keepPred = (it) => keepSet.has(it.name)
4203	      || (keepTools && /(_pickaxe|_axe|_shovel|_hoe|_sword|shears|bucket|flint_and_steel|shield|elytra|totem_of_undying)$/.test(it.name))
4204	      || (keepTools && /(_helmet|_chestplate|_leggings|_boots)$/.test(it.name))
4205	      || (keepTools && /^(torch|copper_torch|soul_torch|crafting_table)$/.test(it.name))
4206	      || (keepTools && /^(cooked_|bread$|golden_apple|baked_potato)/.test(it.name));
4207	
4208	    ctx.setPhase('depositing');
4209	    // openBlock has NO internal timeout — a blocked/protected chest would hang forever
4210	    const win = await withTimeout(bot.openContainer(chest), 8000, 'chest_open_timeout');
4211	    const moved = {};
4212	    let chestFull = false;
4213	    let offered = 0;   // #85: what the deposit ACTUALLY had a chance to move, for ASSERTS
4214	    const skipped = [];
4215	    try {
4216	      const plan = win.items().filter((it) => (args.items ? args.items.includes(it.name) : !keepPred(it)));
4217	      offered = plan.reduce((a, it) => a + it.count, 0);
4218	      for (const it of plan) {
4219	        ctx.step();
4220	        try {
4221	          await win.deposit(it.type, null, it.count); // count REQUIRED: null means 1, not "all"
4222	          moved[it.name] = (moved[it.name] || 0) + it.count;
4223	        } catch (e) {
4224	          if (/destination full/i.test(e.message)) { chestFull = true; break; }
4225	          if (/can't find/i.test(e.message)) { skipped.push(it.name); continue; }
4226	          throw e;
4227	        }
4228	        await new Promise((r) => setTimeout(r, 80));
4229	      }
4230	    } finally {
4231	      try { win.close(); } catch (_) {}
4232	    }
4233	    const total = Object.values(moved).reduce((a, b2) => a + b2, 0);
4234	    if (total > 0) {
4235	      // DEPOT.md rule: chat is the shared ledger
4236	      ctx.say(('DEPOT ' + Object.entries(moved).map(([k, v]) => `+${v} ${k}`).join(' ')).slice(0, 140));
4237	    }
4238	    // #69 gap 1: log every visit, zero-moved included (e.g. chestFull on the first item).
4239	    try { const m = MET(); if (m && m.chest) m.chest('deposit', [chest.position.x, chest.position.y, chest.position.z], moved); } catch (_) {}
4240	    return {
4241	      chest: { x: chest.position.x, y: chest.position.y, z: chest.position.z, name: chest.name },
4242	      moved, totalMoved: total, offered, skipped, chestFull, freeSlotsAfter: bot.inventory.emptySlotCount(),
4243	    };
4244	  },
4245	  doneMsg: (t) => (t.result.chestFull
4246	    ? `Chest is full — deposited ${t.result.totalMoved} items, the rest stays with me.`
4247	    : `Deposited ${t.result.totalMoved} items, kept my gear.`),

